import Mailgun from 'mailgun.js';
import FormData from 'form-data';

const mailgun = new Mailgun(FormData);
const client = mailgun.client({
  username: 'api',
  key: process.env.MAILGUN_API_KEY ?? '',
});

const DOMAIN = process.env.MAILGUN_DOMAIN ?? '';

interface SendEmailOptions {
  to: string;
  subject: string;
  templateName: string;
  variables: Record<string, string>;
}

async function sendTransactionalEmail(options: SendEmailOptions): Promise<string> {
  const result = await client.messages.create(DOMAIN, {
    from: `My App <noreply@${DOMAIN}>`,
    to: [options.to],
    subject: options.subject,
    template: options.templateName,
    'h:X-Mailgun-Variables': JSON.stringify(options.variables),
  });

  console.log('Message queued:', result.id);
  return result.id;
}

// Send a password reset email using a Mailgun template
const messageId = await sendTransactionalEmail({
  to: 'user@example.com',
  subject: 'Reset your password',
  templateName: 'password-reset',
  variables: {
    name: 'Alice',
    reset_link: 'https://myapp.com/reset?token=abc123',
    expiry_hours: '24',
  },
});

import express, { Request, Response } from 'express';
import crypto from 'crypto';

const app = express();

// Mailgun sends inbound emails as multipart/form-data
app.use(express.urlencoded({ extended: true }));

function verifyMailgunSignature(
  timestamp: string,
  token: string,
  signature: string
): boolean {
  const signingKey = process.env.MAILGUN_WEBHOOK_SIGNING_KEY ?? '';
  const value = timestamp + token;
  const hash = crypto
    .createHmac('sha256', signingKey)
    .update(value)
    .digest('hex');
  return hash === signature;
}

app.post('/webhooks/mailgun/inbound', (req: Request, res: Response): void => {
  const { timestamp, token, signature } = req.body as {
    timestamp: string;
    token: string;
    signature: string;
  };

  // Always verify the webhook signature to prevent spoofing
  if (!verifyMailgunSignature(timestamp, token, signature)) {
    res.status(401).json({ error: 'Invalid signature' });
    return;
  }

  const sender = req.body['sender'] as string;
  const subject = req.body['subject'] as string;
  const bodyText = req.body['body-plain'] as string;
  const recipient = req.body['recipient'] as string;

  console.log(`Inbound email from ${sender} to ${recipient}: ${subject}`);
  console.log('Body:', bodyText.slice(0, 200));

  // Process the email (e.g., create a support ticket)
  // ...

  // Mailgun expects a 200 response to acknowledge receipt
  res.status(200).json({ status: 'received' });
});

app.listen(3000, () => console.log('Webhook server running on port 3000'));
